// The one script a prefixed-language page loads for its interface words (I18N-10, 2026-10-22).
//
// Until I18N-10 every English, Spanish, German and French page loaded assets/site-i18n.js — the engine AND the
// words of all five languages (45 991 bytes, 13 961 gzip), four fifths of which no page ever used, and each new
// language (ZH-Hans, KO next) would have grown it for everyone. Now:
//
//   assets/i18n/<code>.js        the words of ONE language (the source; edit here)
//   assets/site-i18n.js          the engine, no words (the source; in Node it reads every words file)
//   assets/site-i18n-<prefix>.js THE BUNDLE a page loads = that language's words file + the engine, byte for byte,
//                                written by this module — GENERATED, never edited by hand
//
// One bundle per page means the same ONE request as before, no second round trip and no change in the order of
// the deferred scripts (the bundle stands exactly where site-i18n.js stood). A bundle is written only for a
// PUBLISHED prefixed language (seo/locales.mjs): a file under /assets/ is a public URL. The Russian pages load
// none — they are written in Russian.
//
// seo/test-site-i18n-split.mjs holds every committed bundle equal to bundleSource(), the words to their keys, and
// every page to its own language's bundle.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { locale, LOCALES } from './locales.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

/** The words file of a language (repository path). */
export const wordsFile = (code) => `assets/i18n/${code}.js`;

/** The bundle a page of this language loads: its repository path and its URL. */
export function siteI18nBundle(code) {
  const L = locale(code);
  if (!L || !L.prefix) throw new Error(`site-i18n-bundle: ${String(code)} has no prefix — the root language loads no bundle`);
  const path = `assets/site-i18n-${L.prefix}.js`;
  return { path, src: `/${path}` };
}

/** The bundle's text: a generated-file note, the words, the engine. Pure apart from reading the two sources. */
export function bundleSource(code) {
  const { path } = siteI18nBundle(code);
  const words = wordsFile(code);
  if (!existsSync(join(ROOT, words))) throw new Error(`site-i18n-bundle: ${code} has no words file (${words})`);
  return `/* ${path} — GENERATED by seo/site-i18n-bundle.mjs from ${words} + assets/site-i18n.js. Do not edit. */\n`
    + readFileSync(join(ROOT, words), 'utf8')
    + readFileSync(join(ROOT, 'assets/site-i18n.js'), 'utf8');
}

/** The languages that get a bundle: published (site.enabled) and prefixed. */
export const bundledLocales = (list = LOCALES) => list.filter((l) => l.prefix && l.site.enabled).map((l) => l.code);

/** Write one language's bundle (before its pages: the pages stamp asset versions from file contents). */
export function writeSiteI18nBundle(code) {
  if (!bundledLocales().includes(code)) throw new Error(`site-i18n-bundle: ${code} is not a published prefixed language — refusing to write a public file`);
  const { path } = siteI18nBundle(code);
  writeFileSync(join(ROOT, path), bundleSource(code));
  return path;
}
